import React from 'react';
import {
  LinImageUpload,
  type LinImageUploadApi,
  type LinImageUploadItem,
} from '@linm-soft-org/linm-web-common-components';
import { filesEndpoint } from '../../../services/files/endpoint';
import { useAppToast } from '../../../hooks/useAppToast';
import {
  scykImageUploadConfig,
  scykImageUploadLabels,
} from '../../../config/scykImageUpload';
import type { MedicalIncidentAttachment } from '../../../models/MedicalIncident';
import styles from '../MedicalIncidentFormPage.module.css';

/** Overlay Common may lag ForkTsChecker — keep displayName on the form item. */
export type IncidentUploadItem = LinImageUploadItem & { displayName?: string };

export interface IncidentDocumentsTabProps {
  entityId?: string;
  items: IncidentUploadItem[];
  onChange: (items: IncidentUploadItem[]) => void;
  disabled?: boolean;
  /** Edit form: confirm before remove. Create: abort immediately. */
  confirmRemove?: boolean;
}

export function resolveUploadDisplayName(item: IncidentUploadItem): string {
  return (item.displayName || item.fileName).trim() || item.fileName;
}

export function attachmentsToUploadItems(
  rows: MedicalIncidentAttachment[] | undefined,
): IncidentUploadItem[] {
  return (rows ?? []).map((row, index) => ({
    localId: row.attachmentId || `committed-${index}`,
    fileName: row.fileName,
    displayName: row.fileName,
    sizeBytes: row.sizeBytes,
    contentType: row.contentType,
    attachmentId: row.attachmentId,
    objectKey: row.objectKey,
    status: 'committed',
  }));
}

export const IncidentDocumentsTab: React.FC<IncidentDocumentsTabProps> = ({
  entityId,
  items,
  onChange,
  disabled = false,
  confirmRemove = false,
}) => {
  const toast = useAppToast();
  const fileErrorMessage = (err: unknown): string => (
    err instanceof Error && err.message
      ? err.message
      : scykImageUploadLabels.objectMissing || 'Chưa tìm thấy file trên storage (chưa PUT hoặc đã xóa).'
  );

  return (
    <div className={styles.tabSection} id="field-section-attachments" data-testid="medical-incident-section-attachments">
      <h3>Tài Liệu / Bằng Chứng</h3>
      <LinImageUpload
        purpose={scykImageUploadConfig.purpose}
        product={scykImageUploadConfig.product}
        entityType={scykImageUploadConfig.entityType}
        entityId={entityId}
        items={items}
        onChange={onChange}
        minFiles={scykImageUploadConfig.minFiles}
        maxFiles={scykImageUploadConfig.maxFiles}
        maxBytes={scykImageUploadConfig.maxBytes}
        accept={scykImageUploadConfig.accept}
        disabled={disabled}
        confirmRemove={confirmRemove}
        showModalActions={false}
        labels={scykImageUploadLabels}
        client={{
          init: filesEndpoint.init,
          complete: async (uploadId, objectKey) => {
            try {
              await filesEndpoint.complete(uploadId, objectKey);
            } catch (err) {
              toast.error(fileErrorMessage(err));
              throw err;
            }
          },
          abort: filesEndpoint.abort,
          getObject: async (attachmentId: string) => {
            try {
              return await filesEndpoint.getObject(attachmentId);
            } catch (err) {
              toast.error(fileErrorMessage(err));
              throw err;
            }
          },
        } satisfies LinImageUploadApi}
        testId="medical-incident-field-attachments"
      />
    </div>
  );
};
